// Modern world module, part 6: "Test the claims" rebuilt around how people actually lived.
const h = Lab.h;
const M = Lab.MODERN;
const PAL = ['#2563EB', '#DC2626', '#16A34A', '#CA8A04', '#9333EA', '#0891B2', '#EA580C', '#DB2777'];
const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim() || '#888';
const REL = ['cm', 'mmr', 'pov', 'epov', 'murder', 'inc', 'undern', 'stunt', 'slums'];
const DIM_ICON = { 'Health': '🩺', 'Food': '🍚', 'Education': '📚', 'Home & services': '🏠', 'Money & poverty': '💵', 'Safety & freedom': '🕊️', 'Community & life satisfaction': '🤝' };
let W = null;
const load = async () => (W ||= await Lab.json('data/wellbeing.json'));
const V = (k) => W.vars.find((v) => v.k === k);
const series = (k, ent) => { const i = W.ents.indexOf(ent); const a = W.data[k] && W.data[k][i]; if (!a) return []; const y0 = a[0]; const out = []; for (let j = 1; j < a.length; j++) if (a[j] != null) out.push([y0 + j - 1, a[j]]); return out; };
const at = (k, ent, y, tol = 3) => { const s = series(k, ent); let best = null, bd = 1e9; s.forEach(([yy, v]) => { const d = Math.abs(yy - y); if (d < bd) { bd = d; best = [yy, v]; } }); return best && bd <= tol ? best : null; };
const fmt = (v) => (v == null ? '—' : Math.abs(v) >= 100 ? Lab.fmt(v) : Math.abs(v) >= 10 ? String(+v.toFixed(1)) : String(+v.toFixed(2)));

// ---------- mini line chart ----------
function chart(k, ents, opt = {}) {
  const v = V(k); const H = opt.big ? 340 : 170; const box = h('div', { class: 'viz', style: { height: H + 'px', position: 'relative', cursor: opt.onClick ? 'zoom-in' : 'crosshair' } }); const c = h('canvas'); box.append(c); const tip = h('div', { style: { position: 'absolute', top: '4px', right: '6px', fontSize: '11px', background: 'var(--card)', padding: '3px 6px', borderRadius: '6px', pointerEvents: 'none', display: 'none', maxWidth: '70%' } }); box.append(tip);
  const S = ents.map((e) => series(k, e).filter(([y]) => (!opt.y0 || y >= opt.y0) && (!opt.y1 || y <= opt.y1)));
  const all = S.flat(); let draw = () => {};
  if (!all.length) { box.style.height = '60px'; box.append(h('div', { class: 'tiny muted', style: { padding: '20px 10px', textAlign: 'center' } }, 'No data for these countries in this period.')); return box; }
  const x0 = opt.y0 || Math.min(...all.map((p) => p[0])), x1 = opt.y1 || Math.max(...all.map((p) => p[0])); let lo = Math.min(...all.map((p) => p[1])), hi = Math.max(...all.map((p) => p[1])); if (lo > 0 && lo < hi * 0.35) lo = 0; const pad = (hi - lo) * 0.08 || 1; lo -= lo === 0 ? 0 : pad; hi += pad; if (/%|0–100/.test(v.u) && hi > 100 && Math.max(...all.map((p) => p[1])) <= 100) hi = 100;
  const ctx = c.getContext('2d'); let Wd, Ht; const L = 34, R = 8, T = 8, B = 18; const X = (x) => L + ((x - x0) / Math.max(1, x1 - x0)) * (Wd - L - R), Y = (y) => Ht - B - ((y - lo) / (hi - lo)) * (Ht - B - T);
  draw = (hx) => { const d = Math.min(2, devicePixelRatio || 1); Wd = box.clientWidth; Ht = box.clientHeight; c.width = Wd * d; c.height = Ht * d; c.style.width = Wd + 'px'; c.style.height = Ht + 'px'; ctx.setTransform(d, 0, 0, d, 0, 0); ctx.clearRect(0, 0, Wd, Ht);
    ctx.font = '10px Inter, sans-serif'; ctx.fillStyle = css('--muted'); ctx.strokeStyle = css('--line'); ctx.lineWidth = 1;
    [lo, (lo + hi) / 2, hi].forEach((y) => { ctx.beginPath(); ctx.moveTo(L, Y(y)); ctx.lineTo(Wd - R, Y(y)); ctx.stroke(); ctx.textAlign = 'right'; ctx.fillText(fmt(y), L - 3, Y(y) + 3); });
    [[x0, 'left'], [Math.round((x0 + x1) / 2), 'center'], [x1, 'right']].forEach(([x, al]) => { ctx.textAlign = al; ctx.fillText(x, X(x), Ht - 4); });
    (opt.events || []).forEach(([y, lab]) => { if (y < x0 || y > x1) return; ctx.strokeStyle = '#94A3B8'; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(X(y), T); ctx.lineTo(X(y), Ht - B); ctx.stroke(); ctx.setLineDash([]); if (opt.big) { ctx.save(); ctx.translate(X(y) + 3, T + 2); ctx.rotate(Math.PI / 2); ctx.textAlign = 'left'; ctx.fillStyle = css('--muted'); ctx.fillText(lab, 0, 0); ctx.restore(); } });
    S.forEach((s, i) => { const gaps = s.slice(1).map((p, j) => p[0] - s[j][0]).sort((a, b) => a - b); const mg = gaps.length ? gaps[gaps.length >> 1] : 1; ctx.strokeStyle = PAL[i % 8]; ctx.lineWidth = opt.big ? 2.5 : 2; ctx.beginPath(); let pen = false, prev = null; s.forEach(([x, y]) => { if (prev != null && x - prev > Math.max(3, mg * 2.5)) pen = false; pen ? ctx.lineTo(X(x), Y(y)) : ctx.moveTo(X(x), Y(y)); pen = true; prev = x; }); ctx.stroke(); if (s.length < 6 || mg > 2) s.forEach(([x, y]) => { ctx.fillStyle = PAL[i % 8]; ctx.beginPath(); ctx.arc(X(x), Y(y), 2.5, 0, 7); ctx.fill(); }); });
    if (hx != null) { ctx.strokeStyle = css('--ink'); ctx.beginPath(); ctx.moveTo(X(hx), T); ctx.lineTo(X(hx), Ht - B); ctx.stroke(); } };
  const ro = new ResizeObserver(() => draw()); ro.observe(box); setTimeout(() => draw(), 0);
  box.onmousemove = (e) => { const r = c.getBoundingClientRect(); const x = Math.round(x0 + ((e.clientX - r.left - L) / (Wd - L - R)) * (x1 - x0)); if (x < x0 || x > x1) return; draw(x); tip.style.display = 'block'; tip.innerHTML = `<b>${x}</b> ` + ents.map((en, i) => { const p = at(k, en, x, 1); return p ? `<span style="color:${PAL[i % 8]}">${en}: ${fmt(p[1])}</span>` : ''; }).filter(Boolean).join(' · '); };
  box.onmouseleave = () => { tip.style.display = 'none'; draw(); };
  if (opt.onClick) box.onclick = opt.onClick;
  return box;
}
const card = (k, ents, opt) => { const v = V(k); const wrap = h('div', { class: 'card', style: { boxShadow: 'none', padding: '10px' } }); let big = false;
  const render = () => { wrap.innerHTML = ''; wrap.style.gridColumn = big ? '1 / -1' : ''; wrap.append(h('div', { style: { marginBottom: '4px', minHeight: '38px' } }, h('b', { class: 'small' }, DIM_ICON[v.dim] + ' ' + v.n), h('div', { class: 'tiny muted' }, (v.good === 'up' ? '↑ higher is better' : '↓ lower is better') + ' · ' + v.u)), chart(k, ents, { ...opt, big, onClick: () => { big = !big; render(); } })); };
  render(); return wrap; };
const legend = (ents) => h('div', { class: 'row', style: { gap: '10px', margin: '6px 0' } }, ents.map((e, i) => h('span', { class: 'small' }, h('span', { style: { display: 'inline-block', width: '12px', height: '4px', background: PAL[i % 8], borderRadius: '2px', marginRight: '4px', verticalAlign: 'middle' } }), e)));

// ---------- before / after table ----------
function beforeAfter(keys, ents, year, win = 15) {
  const rows = [];
  keys.forEach((k) => { const v = V(k); ents.forEach((e, i) => { const a = at(k, e, year - win, 4), b = at(k, e, year, 3), c = at(k, e, year + win, 4); if (!b || (!a && !c)) return;
    const rel = REL.includes(k); const rate = (p, q) => (p && q && (!rel || (p[1] > 0 && q[1] > 0)) ? ((rel ? Math.log(q[1] / p[1]) : q[1] - p[1]) / Math.max(1, q[0] - p[0])) * 10 : null); const r1 = rate(a, b), r2 = rate(b, c); const sgn = v.good === 'up' ? 1 : -1; const eps = rel ? 0.03 : Math.abs(b[1]) * 0.01 + 1e-9;
    const verdict = r1 == null || r2 == null ? '' : r2 * sgn < -eps ? (r1 * sgn < -eps ? '▼ still getting worse' : '▼ turned worse') : r1 * sgn < -eps ? '▲ turned around (was worsening)' : (r2 - r1) * sgn > Math.abs(r1) * 0.25 + eps ? '▲ faster improvement' : (r2 - r1) * sgn < -(Math.abs(r1) * 0.25 + eps) ? '▽ slower improvement' : '≈ same pace';
    rows.push(h('tr', null, h('td', { style: { padding: '3px 6px' } }, DIM_ICON[v.dim] + ' ' + v.n), h('td', { style: { padding: '3px 6px', color: PAL[i % 8], fontWeight: 600 } }, e), h('td', { style: { textAlign: 'right', padding: '3px 6px' } }, a ? fmt(a[1]) : '—'), h('td', { style: { textAlign: 'right', padding: '3px 6px', fontWeight: 700 } }, fmt(b[1])), h('td', { style: { textAlign: 'right', padding: '3px 6px' } }, c ? fmt(c[1]) : '—'),
      h('td', { style: { padding: '3px 6px', color: verdict.startsWith('▲') ? '#16A34A' : verdict.startsWith('▼') ? '#DC2626' : verdict.startsWith('▽') ? '#CA8A04' : css('--muted') } }, verdict))); }); });
  if (!rows.length) return h('p', { class: 'small muted' }, 'Not enough data around ' + year + ' for a before/after comparison.');
  return h('div', { style: { overflowX: 'auto' } }, h('table', { class: 'small', style: { borderCollapse: 'collapse', width: '100%' } }, h('tr', null, ['Indicator', 'Country', `${year - win}`, `${year}`, `${year + win}`, `Trend after vs before`].map((t) => h('th', { style: { textAlign: 'left', padding: '4px 6px', borderBottom: '2px solid var(--line)' } }, t))), rows),
    h('p', { class: 'tiny muted' }, `“Trend” compares the change per decade in the ${win} years after ${year} with the ${win} years before (nearest available years). Death rates, poverty and income are compared in percentage terms (a fall from 160 to 80 counts the same as 20 to 10); the rest in absolute terms. A slower improvement is still an improvement.`));
}

// ---------- the case files ----------
M.cases = [
  { id: 'koreas', t: 'Two Koreas: same people, different systems', q: 'How did ordinary North and South Koreans live after the 1945 division?', ents: ['North Korea', 'South Korea'], y0: 1940, events: [[1945, 'Division'], [1950, 'Korean War'], [1987, 'South democratizes'], [1994, 'North famine begins']], ev: 1970, keys: ['lex', 'cm', 'kcal', 'height', 'stunt', 'school', 'inc', 'free', 'elec'], predict: ['lex', 'kcal', 'cm'],
    life: [['Before', 'Japanese colonial rule (1910–45): forced labor and conscription; most Koreans were poor rural tenants. The industrial north was richer than the agricultural south.'], ['North Korea', 'State-assigned housing, jobs and rations through the Public Distribution System; free healthcare and schooling on paper. Each family is ranked by political loyalty (songbun), which shapes where they may live and work. The 1994–98 famine killed an estimated 600,000 to 1 million people (estimates range more widely). A 2014 UN inquiry documented political prison camps holding tens of thousands.'], ['South Korea', 'Military dictatorships until 1987 with harsh labor repression, then democracy. Very fast growth, mass urbanization, near-universal schooling and national health insurance (1989). Today: among the world’s longest work hours and lowest birth rates, high elderly poverty.']],
    pro: 'Supporters of the North cite free housing, healthcare and education, and blame sanctions and the US for hardship. Defenders of the South’s path credit markets, exports and US alliance.', con: 'Critics of the North cite the famine, prison camps and lack of any freedom. Critics of the South’s path note decades of dictatorship, state-directed industry (not free markets alone), and overwork.', caveat: 'North Korean data are sparse and often estimated by outside agencies (FAO, UN). The North was likely better off than the South until about the 1970s.' },
  { id: 'cuba', t: 'Cuba vs its Caribbean neighbors', q: 'Did the 1959 revolution improve daily life compared with similar countries?', ents: ['Cuba', 'Dominican Republic', 'Haiti', 'Jamaica', 'Costa Rica'], y0: 1940, events: [[1959, 'Revolution'], [1962, 'US embargo'], [1991, 'Soviet aid ends'], [2021, 'Protests']], ev: 1959, keys: ['lex', 'cm', 'docs', 'school', 'kcal', 'inc', 'free', 'murder', 'water'], predict: ['cm', 'school', 'kcal'],
    life: [['Before', 'Batista dictatorship; Havana prosperous, rural Cuba poor. Cuba already had above-average health and literacy for Latin America.'], ['After 1959', 'Land reform, nationalization, the 1961 literacy campaign, free universal healthcare and education, a family doctor in every neighborhood (1984), and a ration book (libreta) since 1962. Housing shortages and crumbling buildings persist. No free elections, press or independent unions; political prisoners; over a million emigrated.'], ['Special Period (1991–95)', 'Soviet aid ended: food energy fell sharply; adults lost an average of about 5 kg (Franco et al., 2013) and an optic neuropathy epidemic linked to poor diet hit about 50,000 people.'], ['Since 2020', 'Severe shortages, blackouts and inflation; hundreds of thousands left in 2022–23, one of the largest emigrations in Cuban history.']],
    pro: 'Supporters point to child mortality and life expectancy rivaling rich countries on a fraction of their income, and blame the US embargo for shortages.', con: 'Critics point to political repression, material poverty, food rationing and emigration, and question how infant deaths are recorded.', caveat: 'Compare Costa Rica, a democracy with no army since 1948, which reached similar health results by a different route.' },
  { id: 'china', t: 'China: Mao era and reform era', q: 'How did life change for ordinary Chinese after 1949 and after 1978?', ents: ['China', 'India'], y0: 1930, events: [[1949, 'PRC founded'], [1959, 'Great Famine'], [1966, 'Cultural Revolution'], [1978, 'Reforms begin'], [2001, 'Joins WTO']], ev: 1978, keys: ['lex', 'cm', 'kcal', 'height', 'school', 'inc', 'pov', 'epov', 'gini', 'free', 'happy'], predict: ['lex', 'pov', 'gini'],
    life: [['Before 1949', 'Civil war and Japanese invasion; most people were landless or poor peasants; very high child mortality and illiteracy.'], ['Mao era', 'Land reform (estimates of landlords killed range from about 1 to 2 million or more), collectives, work units (danwei) providing housing and services, mass literacy and “barefoot doctors” bringing basic care to villages. The Great Leap famine (1959–61) killed an estimated 15 to 45 million. The Cultural Revolution persecuted millions. Residence permits (hukou) tied peasants to the land.'], ['Reform era', 'Household farming, private business and exports; about 800 million people left extreme poverty. But the old rural health system collapsed in the 1980s and was only rebuilt with new insurance after 2003; hundreds of millions of migrant workers lacked city services; inequality rose sharply; political freedoms tightened again after 2012.']],
    pro: 'Supporters of the Mao era credit it with doubling life expectancy and laying foundations (literacy, health, land reform). Supporters of reform credit markets for the largest poverty reduction in history.', con: 'Critics of Mao point to the deadliest famine in history and political terror; critics of the reform era point to inequality, pollution, loss of public services in the 1980s–90s and one-party repression.', caveat: 'Many life expectancy gains came from public health measures (vaccination, sanitation) that also spread in other poor countries after 1950. Compare India.' },
  { id: 'india', t: 'India under British rule and after independence', q: 'Did life improve faster under colonial rule or after 1947?', ents: ['India', 'Pakistan', 'Bangladesh'], y0: 1850, events: [[1877, 'Great Famine'], [1918, 'Flu pandemic'], [1943, 'Bengal famine'], [1947, 'Independence'], [1991, 'Liberalization']], ev: 1947, keys: ['lex', 'cm', 'height', 'kcal', 'school', 'inc', 'pov', 'epov', 'sanit'], predict: ['lex', 'cm', 'school'],
    life: [['Under the Raj', 'Railways, irrigation canals and a few universities; heavy land taxes, exports of grain during famines, and repeated famines (1876–78: about 5.5 to 10 million dead; Bengal 1943: about 3 million). Life expectancy stayed in the 20s into the 1920s; the 1918 flu killed perhaps 12–18 million Indians.'], ['After 1947', 'Partition violence killed hundreds of thousands to perhaps 2 million. Democracy, land reforms in some states, the Green Revolution in the late 1960s ended large famines, and a fast rise in schooling. But child stunting stayed high (about a third of children today) and sanitation lagged for decades.'], ['After 1991', 'Faster growth and poverty reduction; a large informal workforce with little social protection.']],
    pro: 'Defenders of colonial rule cite railways, law and administration. Critics of colonialism cite stagnation, famines and drain of wealth.', con: 'Critics of post-independence policy cite slow growth before 1980 (“Hindu rate of growth”), corruption and poor public services.', caveat: 'Medicine (antibiotics, vaccines) spread worldwide after 1945, so part of the post-1947 gains would likely have come anyway; the comparison is about pace.' },
  { id: 'russia', t: 'Soviet Union to Russia', q: 'How did daily life change through Soviet rule, collapse and recovery?', ents: ['Russia', 'Ukraine', 'Poland', 'Belarus'], y0: 1900, events: [[1917, 'Revolution'], [1932, 'Famine'], [1941, 'Nazi invasion'], [1991, 'USSR collapses'], [2000, 'Putin']], ev: 1991, keys: ['lex', 'cm', 'murder', 'inc', 'pov', 'gini', 'kcal', 'free', 'happy'], predict: ['lex', 'murder', 'gini'],
    life: [['Soviet era', 'Guaranteed jobs, very low rents and free healthcare and education; mass literacy. But housing waiting lists of years, communal apartments, chronic shortages and queues, no free speech, and the Gulag and famines under Stalin (the 1932–33 famine killed about 5–7 million, including the Holodomor in Ukraine). Male life expectancy stagnated from the 1960s, partly from alcohol.'], ['1990s', 'Shock therapy and collapse: prices rose about 2,500% in 1992, wages went unpaid for months, savings vanished, murders and suicides surged, and male life expectancy fell to about 58 by 1994. A few insiders became billionaires buying state companies.'], ['2000s–', 'Oil-driven recovery in incomes and life expectancy; shrinking freedoms; war since 2022.']],
    pro: 'Supporters of Soviet socialism point to security, equality and the absence of homelessness; supporters of the transition point to Poland’s success and say Russia’s problems came from Soviet decay and corruption.', con: 'Critics of the Soviet system cite repression, famine and shortages; critics of shock therapy cite the 1990s mortality crisis (Stuckler, King & McKee, 2009, linked mass privatization to deaths; others dispute this).', caveat: 'Soviet statistics were manipulated; Gapminder values for Russia before 1991 are partly reconstructed.' },
  { id: 'chile', t: 'Chile: Allende, Pinochet and democracy', q: 'Did living conditions improve under the dictatorship, or after it?', ents: ['Chile', 'Argentina', 'Uruguay', 'Peru'], y0: 1955, events: [[1970, 'Allende elected'], [1973, 'Coup'], [1982, 'Crash'], [1990, 'Democracy returns'], [2019, 'Protests']], ev: 1973, keys: ['lex', 'cm', 'pov', 'epov', 'gini', 'inc', 'school', 'free', 'happy', 'murder'], predict: ['cm', 'pov', 'gini'],
    life: [['Allende (1970–73)', 'Land reform, nationalized copper, free milk for children; then shortages, black markets and inflation of several hundred percent by 1973.'], ['Dictatorship (1973–90)', 'About 3,200 killed or disappeared and around 38,000 tortured (official commissions). Unions banned, privatized pensions and schools, unemployment above 20% in the 1983 crisis. Targeted programs kept cutting infant mortality.'], ['Democracy (1990–)', 'Poverty fell from about 40% to under 10% by the 2010s as democratic governments kept the market model and added social spending. Inequality, debt and costs of private pensions, health and education sparked mass protests in 2019.']],
    pro: 'Supporters of the dictatorship’s reforms credit them for Chile’s later prosperity; supporters of Allende say US sabotage caused the crisis.', con: 'Critics of the dictatorship cite murder and torture and argue gains came under democracy; critics of Allende cite economic chaos.', caveat: 'Chile’s infant mortality was already falling before 1973 and kept falling under every government.' },
  { id: 'venezuela', t: 'Venezuela: oil boom, Chávez and collapse', q: 'What happened to food, health and safety from the 1990s to now?', ents: ['Venezuela', 'Colombia', 'Peru'], y0: 1980, events: [[1999, 'Chávez'], [2003, 'Social missions'], [2013, 'Maduro'], [2014, 'Oil price crash'], [2019, 'US oil sanctions']], ev: 2013, keys: ['lex', 'cm', 'mmr', 'kcal', 'undern', 'pov', 'inc', 'murder', 'free', 'happy'], predict: ['undern', 'cm', 'murder'],
    life: [['Chávez years', 'Oil money funded the “missions”: clinics staffed by Cuban doctors (Barrio Adentro), literacy drives and subsidized food; poverty fell in the 2000s. Institutions were weakened and the economy grew more dependent on oil.'], ['Collapse', 'After oil prices fell, hyperinflation, shortages of food and medicine, and blackouts. In a 2017 national survey (ENCOVI), most people reported losing weight in the past year. About 7–8 million people (a quarter of the population) have left the country.'], ['Today', 'Some stabilization through dollarization since 2019; elections widely judged unfree (2024).']],
    pro: 'Supporters credit the early Chávez years with lifting the poor, and blame sanctions, the oil crash and opposition sabotage.', con: 'Critics blame price controls, expropriations, corruption and authoritarianism for the collapse that began before US oil sanctions (2019).', caveat: 'Official statistics stopped being published for years; much data comes from surveys and estimates.' },
  { id: 'welfare', t: 'Welfare states vs the US market model', q: 'Do people live better with large welfare states or with lower taxes and higher incomes?', ents: ['United States', 'Denmark', 'Germany', 'Canada', 'Japan', 'United Kingdom'], y0: 1960, events: [[1965, 'US Medicare'], [1980, 'Reagan/Thatcher era'], [2010, 'Affordable Care Act']], ev: 1980, keys: ['lex', 'cm', 'mmr', 'murder', 'hours', 'gini', 'inc', 'happy', 'trust', 'uhc'], predict: ['lex', 'gini', 'cm'],
    life: [['United States', 'Highest household incomes and largest homes among big economies; employer-based health insurance with about 8% uninsured; high costs for healthcare, childcare and college; medical debt is common; lower life expectancy than peer countries despite spending the most on health.'], ['Nordic & European welfare states', 'Taxes around 40–45% of GDP pay for universal healthcare, free or cheap university, long paid parental leave and strong unemployment insurance. Lower inequality, shorter work hours; critics cite higher taxes, slower startup growth and lower disposable income at the top.']],
    pro: 'Supporters of the US model cite higher incomes, innovation, consumer choice and lower taxes.', con: 'Supporters of welfare states cite longer lives, lower child and maternal mortality, less crime, more leisure and higher reported life satisfaction.', caveat: 'Differences in diet, guns, cars, diversity and history also matter; Denmark and the US differ in many ways at once.' },
  { id: 'africa', t: 'African independence: before and after', q: 'How did health and schooling change after colonial rule ended?', ents: ['Ghana', 'Kenya', 'Nigeria', 'Botswana', 'Tanzania'], y0: 1920, events: [[1957, 'Ghana independent'], [1960, 'Nigeria'], [1963, 'Kenya'], [1966, 'Botswana'], [1985, 'Debt & adjustment'], [1995, 'HIV peak']], ev: 1960, keys: ['lex', 'cm', 'school', 'kcal', 'inc', 'pov', 'water', 'elec', 'free'], predict: ['lex', 'school', 'cm'],
    life: [['Colonial era', 'Forced labor and hut taxes, land taken for settlers (especially in Kenya), very few schools: at independence some colonies had only a handful of university graduates. Kenya’s 1950s emergency detained tens of thousands in camps.'], ['After independence', 'Rapid expansion of schools and clinics in the 1960s–70s; then one-party states, coups, and the 1980s debt crisis with spending cuts under structural adjustment. HIV/AIDS reversed life expectancy gains in southern Africa in the 1990s until treatment spread after 2004. Botswana used diamond revenue under a stable democracy.']],
    pro: 'Defenders of colonialism cite roads, railways and missions; critics of post-colonial leaders cite corruption and authoritarianism.', con: 'Critics of colonialism cite extraction and the deliberate lack of education; critics of the IMF and World Bank cite structural adjustment’s cuts to health and schools.', caveat: 'Data before 1950 are rough reconstructions. Independence dates differ by country.' },
  { id: 'southafrica', t: 'South Africa: apartheid and after', q: 'Did life improve for most South Africans after 1994?', ents: ['South Africa', 'Botswana', 'Namibia'], y0: 1950, events: [[1948, 'Apartheid laws'], [1976, 'Soweto uprising'], [1994, 'Democracy'], [2004, 'HIV treatment rollout']], ev: 1994, keys: ['lex', 'cm', 'water', 'sanit', 'elec', 'slums', 'school', 'gini', 'murder', 'pov', 'free', 'happy'], predict: ['elec', 'lex', 'gini'],
    life: [['Apartheid', 'Racial classification decided where you could live, work, study and whom you could marry. About 3.5 million people were forcibly removed from their homes; Black South Africans were confined to townships and “homelands” with inferior “Bantu education”.'], ['After 1994', 'Political freedom; millions of government-built houses, electricity and water connections; social grants now reach a large share of the population. But unemployment around a third, inequality among the world’s highest, very high murder rates. AIDS denialism delayed treatment, costing an estimated 330,000 lives (Chigwedere et al., 2008) before the rollout.']],
    pro: 'Defenders of the ANC era cite expanded services and grants; critics of the past note that apartheid’s spatial and educational legacy is hard to undo.', con: 'Critics of the ANC cite corruption, state failures (electricity blackouts) and joblessness.', caveat: 'The national averages hide huge gaps between races and regions.' },
  { id: 'vietnam', t: 'Vietnam: war, reunification and Đổi Mới', q: 'How did living standards change after 1975 and after the 1986 market reforms?', ents: ['Vietnam', 'Philippines', 'Thailand'], y0: 1950, events: [[1965, 'US war escalates'], [1975, 'Reunification'], [1986, 'Đổi Mới reforms']], ev: 1986, keys: ['lex', 'cm', 'kcal', 'height', 'school', 'inc', 'pov', 'epov', 'elec', 'free'], predict: ['kcal', 'pov', 'lex'],
    life: [['War and after', 'Millions died in the wars (estimates for the American war range from about 1 to over 3 million Vietnamese). After 1975: re-education camps for hundreds of thousands, collectivized farming, and over 800,000 “boat people” fled. By the mid-1980s food was scarce and inflation reached several hundred percent.'], ['After 1986', 'Farm households regained control of land and output; Vietnam became a major rice exporter within a few years; extreme poverty fell dramatically; near-universal electricity. Still a one-party state without free press or independent unions.']],
    pro: 'Supporters credit the Communist Party for independence and later reforms; supporters of markets credit Đổi Mới.', con: 'Critics cite repression and the costs of the collectivization years.', caveat: 'Compare the Philippines, a democracy with more market freedom that saw slower gains in poverty and nutrition.' },
  { id: 'iran', t: 'Iran before and after 1979', q: 'How did health, education and freedom change after the Islamic Revolution?', ents: ['Iran', 'Turkey', 'Iraq'], y0: 1950, events: [[1953, 'CIA-backed coup'], [1963, 'White Revolution'], [1979, 'Revolution'], [1980, 'Iran–Iraq war'], [2012, 'Sanctions']], ev: 1979, keys: ['lex', 'cm', 'mmr', 'school', 'lit', 'inc', 'free', 'happy', 'water'], predict: ['cm', 'school', 'free'],
    life: [['Under the Shah', 'Oil-fueled modernization and land reform, women’s suffrage (1963), but a repressive secret police (SAVAK), huge inequality and rural poverty.'], ['After 1979', 'A theocracy with compulsory veiling and persecution of dissidents and minorities (thousands of political prisoners executed in 1988). A rural network of “health houses” staffed by local health workers cut child mortality sharply; female literacy and university enrollment soared. Sanctions and mismanagement brought high inflation; mass protests in 2009, 2019 and 2022.']],
    pro: 'Supporters of the Islamic Republic cite rural health, schooling and independence from foreign powers.', con: 'Critics cite repression, discrimination against women and minorities, and economic decline.', caveat: 'Health gains also happened in Turkey and elsewhere; the war with Iraq (1980–88) killed hundreds of thousands.' },
  { id: 'bangladesh', t: 'Bangladesh: from famine to fast progress', q: 'How did a very poor new nation cut child deaths so quickly?', ents: ['Bangladesh', 'Pakistan', 'India'], y0: 1950, events: [[1971, 'Independence war'], [1974, 'Famine'], [1980, 'Oral rehydration campaign'], [2013, 'Rana Plaza']], ev: 1990, keys: ['lex', 'cm', 'mmr', 'school', 'kcal', 'stunt', 'inc', 'epov', 'elec', 'free'], predict: ['cm', 'school', 'epov'],
    life: [['Birth of a nation', 'The 1971 war (with mass killings by the Pakistani army, estimates from about 300,000 to 3 million) and the 1974 famine.'], ['Progress', 'NGOs like BRAC trained mothers in about 12 million households to make oral rehydration solution; family planning and girls’ school stipends; a garment industry employing about 4 million, mostly women, with low wages and deadly factory disasters (Rana Plaza, 2013). Politics alternated between rival parties and authoritarian rule; a 2024 uprising toppled the government.']],
    pro: 'Admirers credit NGOs, women’s empowerment and export jobs.', con: 'Critics cite poverty wages, unsafe factories, flooding and climate threats, and corruption.', caveat: 'Pakistan, richer per person for decades, lagged on health and schooling: income is not destiny.' },
  { id: 'iraq', t: 'Iraq: sanctions and war', q: 'What happened to Iraqi children under sanctions and after the 2003 invasion?', ents: ['Iraq', 'Jordan', 'Iran', 'Syria'], y0: 1970, events: [[1980, 'Iran–Iraq war'], [1990, 'Sanctions'], [1996, 'Oil-for-Food'], [2003, 'US invasion'], [2014, 'ISIS']], ev: 1990, keys: ['lex', 'cm', 'kcal', 'inc', 'murder', 'free', 'water', 'elec'], predict: ['cm', 'kcal', 'lex'],
    life: [['1970s', 'An oil boom paid for free healthcare and education; but Saddam Hussein’s dictatorship, and later the Anfal campaign against Kurds (about 50,000–100,000 killed, 1988).'], ['Sanctions (1990–2003)', 'Food rationing, collapse of incomes and hospitals. A 1999 UNICEF survey suggested about 500,000 extra child deaths; a 2017 study (Dyson & Cetorelli, BMJ Global Health) concluded the data had been manipulated by the regime and found no large rise. Hardship was real; its scale is disputed.'], ['After 2003', 'War, insurgency and sectarian violence: documented civilian deaths exceed 200,000 (Iraq Body Count), with survey estimates far higher and debated. Elections and a new constitution; ISIS seized a third of the country in 2014.']],
    pro: 'Supporters of sanctions and the war cite Saddam’s crimes and later democratic elections.', con: 'Critics cite civilian suffering from sanctions and the invasion, launched on false claims of weapons of mass destruction.', caveat: 'A strong example of how numbers themselves become weapons: always ask who collected the data.' },
  { id: 'japan', t: 'Japan: empire, defeat and welfare state', q: 'How did ordinary Japanese lives change from 1900 to today?', ents: ['Japan', 'South Korea', 'United States'], y0: 1890, events: [[1923, 'Great earthquake'], [1937, 'War with China'], [1945, 'Defeat'], [1961, 'Universal health insurance'], [1990, 'Bubble bursts']], ev: 1945, keys: ['lex', 'cm', 'height', 'kcal', 'school', 'inc', 'hours', 'happy', 'murder'], predict: ['lex', 'height', 'cm'],
    life: [['Empire', 'Militarism, censorship and harsh rural poverty; daughters of poor farmers were sometimes sold into factory or sex work. War brought starvation-level rations by 1945 and about 3 million Japanese dead.'], ['Postwar', 'US-led land reform, a new constitution, universal health insurance (1961), lifetime employment in big firms, very low crime and the world’s longest life expectancy. Long work hours (karoshi, “death from overwork”), a rapidly aging population and, since 1990, stagnant wages.']],
    pro: 'Admirers credit a cohesive society, strong public health and egalitarian growth.', con: 'Critics note conformity pressures, overwork, gender inequality and long stagnation.', caveat: 'Japanese men born around 1980 were about 13 cm taller than those born around 1900 (see the height chart): adult height reflects childhood nutrition and health, so it records how children lived decades earlier.' },
  { id: 'world', t: 'Has life gotten better for most people since 1800?', q: 'Is the long-run story one of progress?', ents: ['World'], y0: 1800, events: [[1918, 'Flu pandemic'], [1945, 'End of WWII'], [1959, 'China famine'], [2020, 'COVID-19']], ev: 1950, keys: ['lex', 'cm', 'pov', 'epov'], predict: ['lex', 'cm', 'pov'],
    life: [['1800', 'Most people were farmers; over 40% of children died before age 5; famines and epidemics were routine; very few could read.'], ['Today', 'Child mortality around 4%; average life expectancy above 70; most people can read. Yet hundreds of millions still lack enough food, clean water or decent housing.']],
    pro: 'Optimists (Hans Rosling, Steven Pinker, Max Roser) see science, trade, democracy and public health driving historic progress.', con: 'Critics (Jason Hickel and others) argue poverty lines are set too low, much progress came from China, and colonialism impoverished many before the gains.', caveat: 'Switch between the $2.15 and $6.85 poverty lines: the trend is down at both, but the level is very different.' },
];

