function whyNotGDP() {
  return h('div', { class: 'card' }, h('h2', { style: { marginTop: 0 } }, 'Test the claims: how did people actually live?'),
    h('p', { class: 'small' }, 'Every political system claims it made life better. GDP, the usual yardstick, measures how much is bought and sold, not whether people are healthy, fed, housed, educated, safe, free or connected to others. Simon Kuznets, who designed national income accounts, warned Congress in 1934 that the welfare of a nation can scarcely be inferred from them. Since then, Amartya Sen’s capability approach, the UN Human Development Index (1990) and the Stiglitz–Sen–Fitoussi report (2009) pushed to measure what people can actually be and do.'),
    h('p', { class: 'small' }, 'So these tests use ', h('b', null, `${W.vars.length} measures of how people live`), ', grouped into seven parts of a good life:'),
    h('div', { class: 'row', style: { gap: '6px' } }, Object.entries(DIM_ICON).map(([d, e]) => h('span', { class: 'tag', style: { '--c': '#475569' } }, e + ' ' + d + ' (' + W.vars.filter((v) => v.dim === d).length + ')'))),
    h('details', { style: { marginTop: '8px' } }, h('summary', { class: 'small', style: { cursor: 'pointer' } }, 'See every measure and what it misses'),
      h('ul', { class: 'small', style: { columns: 2 } }, W.vars.map((v) => h('li', null, `${DIM_ICON[v.dim]} ${v.n} (${v.u})`))),
      h('p', { class: 'tiny muted' }, 'What the numbers still miss: dignity, fear, freedom of movement, the quality (not just quantity) of schools and clinics, unpaid care, loneliness, and inequality between groups within a country. That is why every case also has written accounts of daily life. Data before about 1950 are reconstructions by historians and demographers.')),
    Lab.source(W.src));
}

function predictStep(cs, onDone) {
  const box = h('div', { class: 'card', style: { boxShadow: 'none', background: 'var(--card2)' } }); const main = cs.ents[0]; const yrs = 15; let n = 0, right = 0;
  box.append(h('b', null, '🔮 Predict first'), h('p', { class: 'small', style: { margin: '4px 0 8px' } }, `In the ${yrs} years after ${cs.ev}, what happened in ${main}? Guess before you look.`));
  const truth = (k) => { const v = V(k); const a = at(k, main, cs.ev, 4), b = at(k, main, cs.ev + yrs, 5); if (!a || !b) return null; const ch = (b[1] - a[1]) * (v.good === 'up' ? 1 : -1); const rel = Math.abs(b[1] - a[1]) / Math.max(1e-9, Math.abs(a[1])); return rel < 0.03 ? 'same' : ch > 0 ? 'better' : 'worse'; };
  const keys = cs.predict.filter((k) => truth(k)); if (!keys.length) { onDone(); return h('div'); }
  keys.forEach((k) => { const fb = h('span', { class: 'small', style: { marginLeft: '8px' } }); const v = V(k); const t = truth(k); const a = at(k, main, cs.ev, 4), b = at(k, main, cs.ev + yrs, 5);
    box.append(h('div', { class: 'row', style: { margin: '4px 0' } }, h('span', { class: 'small', style: { width: '240px' } }, DIM_ICON[v.dim] + ' ' + v.n), ...['better', 'same', 'worse'].map((g) => h('button', { class: 'btn sm', onclick: (e) => { if (fb.textContent) return; n++; if (g === t) right++; e.target.style.borderColor = g === t ? '#16A34A' : '#DC2626'; fb.innerHTML = `${g === t ? '✓' : '✗'} It got <b>${t}</b>: ${fmt(a[1])} in ${a[0]} → ${fmt(b[1])} in ${b[0]}`; if (n === keys.length) { box.append(h('p', { class: 'small' }, `You got ${right} of ${keys.length}. Now explore the full picture below.`)); onDone(); } } }, g === 'better' ? '↗ Better' : g === 'worse' ? '↘ Worse' : '→ About the same')), fb)); });
  box.append(h('button', { class: 'btn sm', style: { marginTop: '6px' }, onclick: onDone }, 'Skip and show me the data'));
  return box;
}

