  const views = { cases: ['📁 Case files', () => listView(area)], build: ['🧪 Build your own test', () => builder(area)], scatter: ['💸 Same money, different lives', () => scatter(area)], score: ['🧾 Scorecard', () => scorecard(area)], other: ['📈 Other data checks', () => other(area)] };
  const tabs = h('div', { class: 'row', style: { gap: '6px', margin: '10px 0' } }); let cur = 'cases';
  const show = (k) => { cur = k; tabs.querySelectorAll('button').forEach((b) => b.classList.toggle('on', b.dataset.k === k)); area.innerHTML = ''; views[k][1](); };
  Object.entries(views).forEach(([k, [l]]) => tabs.append(h('button', { class: 'tab', 'data-k': k, onclick: () => show(k) }, l)));
  el.append(whyNotGDP(), tabs, area); show('cases');
